	codexHookCommandOS = goos
	codexProductionHookWrapperWorks = func(context.Context, string) bool {
		return wrapperWorks
	}
	t.Cleanup(func() {
		codexHookCommandOS = oldGOOS
		codexProductionHookWrapperWorks = oldProbe
	})
}

